do $test$
declare
  v_log    text := '';
  v_org    uuid;
  v_code   text;
  v_claim  text;
  v_org2   uuid;
  v_claim2 text;
  v_admin_claim   text;
  v_teacher_claim text;
  v_extra_claim   text;
  v_invited_by    text;
  v_member public.organization_members;
