$test$;

-- ── 02_people_access_test.sql ──
do $test$
declare
  v_log  text := '';
  v_n    int;
  v_rows int;
  v_new_staff public.staff;
  v_ok   boolean;
  -- schools and owner codes
  v_org  uuid;  v_claim  text;
  v_org2 uuid;  v_claim2 text;
  -- school A records
  v_teacher_staff uuid;
  v_bursar_staff  uuid;
  v_s1 uuid;
  v_s2 uuid;
  v_p1 uuid;
  v_p2 uuid;
  v_p3 uuid;
  v_names text;
  -- school B records
  v_pb uuid;
  -- claim codes
  v_t_code  text;
  v_t_code2 text;
  v_b_code  text;
  v_p_code  text;
  v_s_code  text;
  -- numbering
  v_num  text;
  v_year text := extract(year from (now() at time zone 'Africa/Lagos')::date)::text;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: two schools, two owners ─────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('School A', 'SCA') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('School B', 'SCB') c;

  -- 00 a school's number prefix must be 2-8 letters or digits
  begin
    perform public.create_organization('Bad Prefix School', 'k!');
    v_log := v_log || E'\nFAIL 00 bad prefix accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 00 bad number prefix rejected [' || sqlerrm || ']';
  end;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bimbo', 'Owner');
  insert into public.parents (organization_id, first_name, last_name, phone)
    values (v_org2, 'Bola', 'Other', '0800000000') returning id into v_pb;
  insert into public.students (organization_id, first_name, last_name, admission_number)
    values (v_org2, 'Tunde', 'Other', 'B001');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');

  -- 01 owner adds staff, students, parents and links
  insert into public.staff (organization_id, first_name, last_name, job_title, phone, email)
    values (v_org, 'Ada', 'Teacher', 'Maths Teacher', '0807777777', 'ada@school.test') returning id into v_teacher_staff;
  insert into public.staff (organization_id, first_name, last_name, job_title, staff_type)
    values (v_org, 'Bayo', 'Bursar', 'Bursar', 'non_teaching') returning id into v_bursar_staff;
  v_s1 := (public.create_student(
    p_organization_id => v_org, p_first_name => 'Chidi', p_last_name => 'Pupil', p_admission_number => 'A001',
    p_photo_id => 'cf-image-id-123', p_blood_group => 'O+', p_genotype => 'AA', p_medical_notes => 'Asthma')).id;
  insert into public.students (organization_id, first_name, last_name, admission_number)
    values (v_org, 'Dayo', 'Pupil', 'A002') returning id into v_s2;
  v_p1 := (public.create_parent(
    p_organization_id => v_org, p_title => 'Mrs', p_first_name => 'Ngozi', p_last_name => 'Pupil', p_phone => '0801111111',
    p_email => 'ngozi@home.test', p_occupation => 'Nurse', p_address => '3 Mother Lane')).id;
  insert into public.student_parents (organization_id, student_id, parent_id, relationship, is_primary_contact)
    values (v_org, v_s1, v_p1, 'mother', true);
  -- an unrelated parent (Dayo's mother) that Chidi's parents must NOT see
  insert into public.parents (organization_id, title, first_name, last_name, phone)
    values (v_org, 'Mrs', 'Funke', 'Other', '0803333333') returning id into v_p3;
  insert into public.student_parents (organization_id, student_id, parent_id, relationship, is_primary_contact)
    values (v_org, v_s2, v_p3, 'mother', true);
  v_log := v_log || E'\nPASS 01 owner adds staff, students, parents and links';
  select count(*) into v_n from public.student_private_details
    where student_id = v_s1 and blood_group = 'O+' and genotype = 'AA' and medical_notes = 'Asthma';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 01b create_student saves profile and private details together';

  -- 02 invite_staff returns a code; asking again returns the same code
  v_t_code  := public.invite_staff(v_teacher_staff);
  v_t_code2 := public.invite_staff(v_teacher_staff);
  v_log := v_log || E'\n' || case when v_t_code ~ '^[A-Z0-9]{8}$' and v_t_code = v_t_code2 then 'PASS' else 'FAIL' end
        || ' 02 invite_staff is repeatable before redeem [' || v_t_code || ' / ' || v_t_code2 || ']';

  -- 03 staff cannot be invited as owner
  begin
    perform public.invite_staff(v_bursar_staff, 'owner');
    v_log := v_log || E'\nFAIL 03 staff invited as owner';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 03 staff cannot be invited as owner [' || sqlerrm || ']';
  end;

  v_b_code := public.invite_staff(v_bursar_staff, 'bursar');
  v_p_code := public.invite_parent(v_p1);
  v_s_code := public.invite_student(v_s1);

  -- 04 member_id is not client-writable
  begin
    update public.staff set member_id = null where id = v_teacher_staff;
    v_log := v_log || E'\nFAIL 04 client wrote member_id';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 04 member_id is not client-writable [' || sqlerrm || ']';
  end;

  -- 05 admission numbers are unique within a school
  begin
    insert into public.students (organization_id, first_name, last_name, admission_number) values (v_org, 'Dup', 'Licate', 'A001');
    v_log := v_log || E'\nFAIL 05 duplicate admission number accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 05 admission number unique per school [' || sqlerrm || ']';
  end;

  -- 05b staff numbers are generated with the prefix given at school creation
  --     (0001 is the owner's own record, made by redeem_claim_code)
  select s.staff_number into v_num from public.staff s where s.id = v_bursar_staff;
  v_log := v_log || E'\n' || case when v_num = 'SCA/STF/0003' then 'PASS' else 'FAIL' end || ' 05b staff number generated [' || v_num || ']';

  -- 05c admission numbers are generated when left blank
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Auto', 'One')
    returning admission_number into v_num;
  v_log := v_log || E'\n' || case when v_num = 'SCA/' || v_year || '/0001' then 'PASS' else 'FAIL' end || ' 05c admission number generated [' || v_num || ']';

  -- 05d owner can correct the prefix (and set the logo id); the counter carries on
  update public.organizations set number_prefix = 'SCX', logo_id = 'cf-logo-id-1' where id = v_org;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Auto', 'Two')
    returning admission_number into v_num;
  v_log := v_log || E'\n' || case when v_num = 'SCX/' || v_year || '/0002' then 'PASS' else 'FAIL' end || ' 05d corrected prefix used [' || v_num || ']';

  -- 05e a number already typed in by the school is skipped
  insert into public.students (organization_id, first_name, last_name, admission_number)
    values (v_org, 'Manual', 'Three', 'SCX/' || v_year || '/0003');
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Auto', 'Four')
    returning admission_number into v_num;
  v_log := v_log || E'\n' || case when v_num = 'SCX/' || v_year || '/0004' then 'PASS' else 'FAIL' end || ' 05e taken number skipped [' || v_num || ']';

  -- 05f admission year comes from admission_date when given (own counter per year)
  insert into public.students (organization_id, first_name, last_name, admission_date) values (v_org, 'Auto', 'Old', '2024-09-10')
    returning admission_number into v_num;
  v_log := v_log || E'\n' || case when v_num = 'SCX/2024/0001' then 'PASS' else 'FAIL' end || ' 05f admission year from admission_date [' || v_num || ']';

  -- remove the numbering students so later counts stay at S1 + S2
  delete from public.students where organization_id = v_org and id not in (v_s1, v_s2);

  -- 06 a student cannot be linked to a parent from another school
  begin
    insert into public.student_parents (organization_id, student_id, parent_id, relationship) values (v_org, v_s1, v_pb, 'guardian');
    v_log := v_log || E'\nFAIL 06 cross-school link accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23503' then 'PASS' else 'FAIL' end || ' 06 cross-school link rejected [' || sqlerrm || ']';
  end;

  -- 07 making a second parent primary clears the first
  v_p2 := (public.create_parent(
    p_organization_id => v_org, p_title => 'Mr', p_first_name => 'Emeka', p_last_name => 'Pupil', p_phone => '0802222222',
    p_email => 'emeka@away.test', p_occupation => 'Engineer', p_address => '9 Father Close')).id;
  insert into public.student_parents (organization_id, student_id, parent_id, relationship, is_primary_contact)
    values (v_org, v_s1, v_p2, 'father', true);
  select count(*) filter (where is_primary_contact), bool_or(parent_id = v_p2 and is_primary_contact)
    into v_n, v_ok
    from public.student_parents where student_id = v_s1;
  v_log := v_log || E'\n' || case when v_n = 1 and v_ok then 'PASS' else 'FAIL' end || ' 07 one primary contact per student';
  select count(*) into v_n from public.parent_private_details
    where parent_id = v_p2 and email = 'emeka@away.test' and occupation = 'Engineer' and address = '9 Father Close';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 07b create_parent saves profile and private details together';

  -- 08 owner A cannot see school B's people
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 08 owner sees only own school''s students [' || v_n || ' rows]';

  -- ── teacher ────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_t_code);

  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 09a teacher with no classes sees no students [' || v_n || ']';
  select count(*) into v_n from public.parents;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 09b teacher with no classes sees no parents [' || v_n || ']';
  select count(*) into v_n from public.staff;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 09c teacher reads all staff profiles in school [' || v_n || ']';
  select count(*) into v_n from public.staff_private_details;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 09d teacher reads only own private details [' || v_n || ']';
  update public.staff_private_details set address = 'Somewhere' where staff_id = v_teacher_staff;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 09e teacher cannot edit own private details yet';
  select count(*) into v_n from public.student_private_details;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 09g teacher with no classes sees no student private details [' || v_n || ']';
  select count(*) into v_n from public.parent_private_details;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 09h teachers see no parent private details [' || v_n || ']';
  begin
    perform public.create_staff(v_org, 'Sneaky', 'Hire');
    v_log := v_log || E'\nFAIL 09f teacher added staff through create_staff';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 09f teacher cannot use create_staff [' || sqlerrm || ']';
  end;

  begin
    insert into public.students (organization_id, first_name, last_name) values (v_org, 'Sneaky', 'Add');
    v_log := v_log || E'\nFAIL 10a teacher added a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 10a teacher cannot add students [' || sqlerrm || ']';
  end;
  update public.students set first_name = 'Changed' where id = v_s1;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 10b teacher cannot edit students';
  begin
    perform public.invite_student(v_s2);
    v_log := v_log || E'\nFAIL 10c teacher issued a login';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 10c teacher cannot issue logins [' || sqlerrm || ']';
  end;

  -- ── bursar ─────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_b_code);

  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 11a bursar reads students [' || v_n || ']';
  select count(*) into v_n from public.student_private_details;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 11a2 bursar sees no student private details [' || v_n || ']';
  select count(*) into v_n from public.parent_private_details;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 11a3 bursar sees parent private details (for fees) [' || v_n || ']';
  select count(*) into v_n from public.staff;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 11b bursar reads all staff [' || v_n || ']';
  select count(*) into v_n from public.staff_private_details;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 11b2 bursar reads all private details [' || v_n || ']';
  begin
    insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Sneaky', 'Hire');
    v_log := v_log || E'\nFAIL 11c bursar added staff';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 11c bursar cannot add staff [' || sqlerrm || ']';
  end;

  -- ── parent ─────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_p_code);

  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 12a parent sees only own child [' || v_n || ']';
  select count(*) into v_n from public.student_private_details where medical_notes = 'Asthma';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 12a2 parent sees own child''s private details [' || v_n || ']';
  select count(*), string_agg(first_name, ', ' order by first_name) into v_n, v_names from public.parents;
  v_log := v_log || E'\n' || case when v_n = 2 and v_names = 'Emeka, Ngozi' then 'PASS' else 'FAIL' end
        || ' 12b parent sees self and child''s other parent, not unrelated parents [' || coalesce(v_names, '') || ']';
  select count(*), string_agg(email, ', ') into v_n, v_names from public.parent_private_details;
  v_log := v_log || E'\n' || case when v_n = 1 and v_names = 'ngozi@home.test' then 'PASS' else 'FAIL' end
        || ' 12b2 parent sees only own private details, not the co-parent''s [' || coalesce(v_names, '') || ']';
  select count(*) into v_n from public.student_parents;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 12c parent sees all of own child''s links, not others [' || v_n || ']';
  select count(*) into v_n from public.staff;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 12d parent sees staff profiles (names) [' || v_n || ']';
  select s.phone || ' / ' || s.email into v_names from public.staff s where s.id = v_teacher_staff;
  v_log := v_log || E'\n' || case when v_names = '0807777777 / ada@school.test' then 'PASS' else 'FAIL' end || ' 12d2 parent sees teacher''s phone and email [' || coalesce(v_names, '') || ']';
  select count(*) into v_n from public.staff_private_details;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 12e parent sees no staff private details [' || v_n || ']';
  begin
    perform public.update_staff(v_teacher_staff, 'Ada', 'Changed', null, null, null, null, null, null, null, null,
                                'teaching', 'active', null, null, null, null);
    v_log := v_log || E'\nFAIL 12f parent edited a staff record';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 12f parent cannot use update_staff [' || sqlerrm || ']';
  end;

  -- ── student ────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_student","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_s_code);

  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 13a student sees only own record [' || v_n || ']';
  select count(*) into v_n from public.student_private_details;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 13a2 student sees own private details [' || v_n || ']';
  select count(*) into v_n from public.student_parents;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 13b student sees own parent links [' || v_n || ']';
  select count(*) into v_n from public.staff;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 13c student sees staff profiles (names) [' || v_n || ']';
  select count(*) into v_n from public.staff_private_details;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 13d student sees no staff private details [' || v_n || ']';
  select count(*) into v_n from public.parent_private_details;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 13d2 student sees no parent private details [' || v_n || ']';

  -- ── owner again ────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';

  -- 13e every staff member got a private details row automatically, and the owner can edit it
  select count(*) into v_n from public.staff_private_details where organization_id = v_org;
  update public.staff_private_details set address = '1 School Road', date_of_birth = '1990-05-01' where staff_id = v_teacher_staff;
  get diagnostics v_rows = row_count;
  v_log := v_log || E'\n' || case when v_n = 3 and v_rows = 1 then 'PASS' else 'FAIL' end || ' 13e details row created with each staff member; owner can edit it [' || v_n || ']';

  -- 13f create_staff saves profile + private details in one call
  v_new_staff := public.create_staff(
    p_organization_id => v_org, p_first_name => 'Femi', p_last_name => 'Coach',
    p_job_title => 'PE Teacher', p_phone => '0806666666',
    p_date_of_birth => '1988-02-14', p_address => '5 Stadium Road', p_employment_date => '2024-09-01');
  select count(*) into v_n from public.staff_private_details d
    where d.staff_id = v_new_staff.id and d.date_of_birth = '1988-02-14' and d.address = '5 Stadium Road' and d.employment_date = '2024-09-01';
  v_log := v_log || E'\n' || case when v_n = 1 and v_new_staff.phone = '0806666666' and v_new_staff.staff_number like 'SC_/STF/%'
        then 'PASS' else 'FAIL' end || ' 13f create_staff saves profile and private details together [' || v_new_staff.staff_number || ']';

  -- 13g update_staff changes both tables in one call; blank staff number keeps the old one
  perform public.update_staff(v_new_staff.id, 'Femi', 'Coach', null, '', null, '0801231234', 'femi@school.test', null, null,
                              'Head of Sports', 'teaching', 'active', '1988-02-14', '9 New Road', 'Lagos', '2024-09-01');
  select count(*) into v_n
    from public.staff s join public.staff_private_details d on d.staff_id = s.id
    where s.id = v_new_staff.id and s.phone = '0801231234' and s.job_title = 'Head of Sports'
      and s.staff_number = v_new_staff.staff_number and d.address = '9 New Road' and d.state_of_origin = 'Lagos';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 13g update_staff saves both tables, keeps staff number';

  -- 13i update_student changes both tables in one call; blank admission number keeps the old one
  perform public.update_student(v_s1, 'Chidi', 'Pupil', 'Emeka', '', 'male', null, 'cf-image-id-123', null,
                                'active', '2015-03-02', '2 Home Street', 'Anambra', 'Awka South', 'O+', 'AS', 'Asthma, uses inhaler');
  select count(*) into v_n
    from public.students st join public.student_private_details d on d.student_id = st.id
    where st.id = v_s1 and st.middle_name = 'Emeka' and st.admission_number = 'A001'
      and d.genotype = 'AS' and d.lga = 'Awka South' and d.medical_notes = 'Asthma, uses inhaler';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 13i update_student saves both tables, keeps admission number';

  -- 13j update_parent changes both tables in one call
  perform public.update_parent(v_p1, 'Ngozi', 'Pupil', '0801111112', 'Dr', 'female', null, null, null,
                               true, 'ngozi@new.test', 'Doctor', '3 Mother Lane');
  select count(*) into v_n
    from public.parents pa join public.parent_private_details d on d.parent_id = pa.id
    where pa.id = v_p1 and pa.title = 'Dr' and pa.phone = '0801111112' and d.email = 'ngozi@new.test' and d.occupation = 'Doctor';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 13j update_parent saves both tables';

  -- keep later staff counts as before
  delete from public.staff where id = v_new_staff.id;

  -- 14 a redeemed login cannot be re-issued
  begin
    perform public.invite_parent(v_p1);
    v_log := v_log || E'\nFAIL 14 login re-issued after redeem';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%already has a login%' then 'PASS' else 'FAIL' end || ' 14 redeemed login cannot be re-issued [' || sqlerrm || ']';
  end;

  -- 15 deleting a parent removes their links
  delete from public.parents where id = v_p2;
  select count(*) into v_n from public.student_parents where student_id = v_s1;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 15 deleting a parent removes their links [' || v_n || ' left]';

  -- 15b another school's owner gets the same generic error for a real record
  --     in School A as for an id that doesn't exist (nothing is revealed)
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.invite_student(v_s2);
    v_log := v_log || E'\nFAIL 15b other school issued a login for School A';
  exception when others then
    v_ok := sqlstate = '42501' and sqlerrm like '%not found, or you can''t issue logins%';
    begin
      perform public.invite_student(gen_random_uuid());
      v_ok := false;
    exception when others then
      v_ok := v_ok and sqlstate = '42501' and sqlerrm like '%not found, or you can''t issue logins%';
    end;
    v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 15b same error for other school''s record and unknown id [' || sqlerrm || ']';
  end;

  -- ── platform admin ─────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 16 platform admin reads students in every school [' || v_n || ']';
  perform public.set_organization_status(v_org, 'suspended');

  -- 17 suspended school: teacher and parent lose access
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 17a suspended school: teacher sees no students [' || v_n || ']';

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 17b suspended school: parent sees no children [' || v_n || ']';

  -- 18 anon has no access
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform count(*) from public.students;
    v_log := v_log || E'\nFAIL 18 anon read students';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 18 anon cannot read students [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('02_people', v_log);
end;
$test$;

-- ── 03_academic_structure_access_test.sql ──
do $test$
declare
  v_log  text := '';
  v_n    int;
  v_rows int;
  v_ok   boolean;
  -- schools
  v_org  uuid;  v_claim  text;
  v_org2 uuid;  v_claim2 text;
  v_org3 uuid;  v_claim3 text;
  v_names text;
  -- people in School A
  v_teacher uuid;  v_t_code text;
  v_teacher2 uuid;
  v_teacher3 uuid;
  v_teacher4 uuid;
  v_bursar uuid;  v_b_code text;
  v_arm uuid;
  v_s1 uuid;  v_s2 uuid;
  v_p1 uuid;  v_p_code text;  v_s_code text;
  -- structure in School A
  v_nursery uuid;  v_primary uuid;  v_secondary uuid;
  v_pry1 uuid;  v_pry2 uuid;  v_jss1 uuid;
  v_pry1a uuid;  v_pry1b uuid;
  v_sess1 uuid;  v_sess2 uuid;
  v_t1 uuid;  v_t2 uuid;  v_t3 uuid;
  -- structure in School B
  v_b_class uuid;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup ──────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('School A', 'SCA') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('School B', 'SCB') c;
  select c.organization_id, c.owner_claim_code into v_org3, v_claim3 from public.create_organization('School C', 'SCC') c;

  -- School B gets one section + class (for cross-school checks)
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bimbo', 'Owner');
  with s as (insert into public.sections (organization_id, name) values (v_org2, 'Primary') returning id)
  insert into public.classes (organization_id, section_id, name) select v_org2, s.id, 'Primary 1' from s returning id into v_b_class;

  -- 00a the standard structure is refused once a school has sections
  begin
    perform public.create_standard_structure(v_org2);
    v_log := v_log || E'\nFAIL 00a standard structure added on top of existing sections';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%already has sections%' then 'PASS' else 'FAIL' end || ' 00a standard structure only for a new school [' || sqlerrm || ']';
  end;

  -- 00b a new school gets Nursery 1–3, Primary 1–6, JSS 1–3, SS 1–3 in promotion order
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_c","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim3, 'Chika', 'Owner');
  v_n := public.create_standard_structure(v_org3);
  select string_agg(c.name, ',' order by s.sort_order, c.sort_order) into v_names
    from public.classes c join public.sections s on s.id = c.section_id
    where c.organization_id = v_org3;
  v_log := v_log || E'\n' || case when v_n = 15
        and v_names = 'Nursery 1,Nursery 2,Nursery 3,Primary 1,Primary 2,Primary 3,Primary 4,Primary 5,Primary 6,JSS 1,JSS 2,JSS 3,SS 1,SS 2,SS 3'
        then 'PASS' else 'FAIL' end || ' 00b standard structure created in promotion order [' || v_n || ' classes]';
  select string_agg(c.name, ',') into v_names from public.classes c where c.organization_id = v_org3 and c.is_graduating_class;
  v_log := v_log || E'\n' || case when v_names = 'SS 3' then 'PASS' else 'FAIL' end || ' 00c SS 3 marked as the graduating class [' || coalesce(v_names, '') || ']';

  -- School A owner sets up people
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada', 'Teacher') returning id into v_teacher;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Bisi', 'Teacher') returning id into v_teacher2;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Kemi', 'Teacher') returning id into v_teacher3;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Lola', 'Teacher') returning id into v_teacher4;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Chidi', 'Pupil') returning id into v_s1;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Dayo', 'Pupil') returning id into v_s2;
  insert into public.parents (organization_id, first_name, last_name, phone) values (v_org, 'Ngozi', 'Pupil', '0801111111') returning id into v_p1;
  insert into public.student_parents (organization_id, student_id, parent_id, relationship, is_primary_contact)
    values (v_org, v_s1, v_p1, 'mother', true);
  v_t_code := public.invite_staff(v_teacher);
  insert into public.staff (organization_id, first_name, last_name, staff_type) values (v_org, 'Bayo', 'Bursar', 'non_teaching') returning id into v_bursar;
  v_b_code := public.invite_staff(v_bursar, 'bursar');
  v_p_code := public.invite_parent(v_p1);
  v_s_code := public.invite_student(v_s1);

  -- 01 owner builds sections → classes → arms
  insert into public.sections (organization_id, name, sort_order, head_staff_id) values (v_org, 'Nursery', 1, null) returning id into v_nursery;
  insert into public.sections (organization_id, name, sort_order, head_staff_id) values (v_org, 'Primary', 2, v_teacher2) returning id into v_primary;
  insert into public.sections (organization_id, name, sort_order) values (v_org, 'Secondary', 3) returning id into v_secondary;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_primary, 'Primary 1', 1) returning id into v_pry1;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_primary, 'Primary 2', 2) returning id into v_pry2;
  insert into public.classes (organization_id, section_id, name, sort_order) values (v_org, v_secondary, 'JSS 1', 1) returning id into v_jss1;
  insert into public.class_arms (organization_id, class_id, name, capacity) values (v_org, v_pry1, 'A', 30) returning id into v_pry1a;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_pry1, 'B') returning id into v_pry1b;
  v_log := v_log || E'\nPASS 01 owner builds sections, classes and arms';

  -- 02 class names are unique in a school (case-insensitive)
  begin
    insert into public.classes (organization_id, section_id, name) values (v_org, v_primary, 'primary 1');
    v_log := v_log || E'\nFAIL 02 duplicate class name accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 02 class name unique per school [' || sqlerrm || ']';
  end;

  -- 03 arm names are unique within a class (case-insensitive)
  begin
    insert into public.class_arms (organization_id, class_id, name) values (v_org, v_pry1, 'a');
    v_log := v_log || E'\nFAIL 03 duplicate arm name accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 03 arm name unique per class [' || sqlerrm || ']';
  end;

  -- 04 an arm cannot hang off another school's class
  begin
    insert into public.class_arms (organization_id, class_id, name) values (v_org, v_b_class, 'X');
    v_log := v_log || E'\nFAIL 04 cross-school arm accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23503' then 'PASS' else 'FAIL' end || ' 04 cross-school arm rejected [' || sqlerrm || ']';
  end;

  -- 05 capacity must be positive
  begin
    insert into public.class_arms (organization_id, class_id, name, capacity) values (v_org, v_pry2, 'A', 0);
    v_log := v_log || E'\nFAIL 05 zero capacity accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 05 capacity must be positive [' || sqlerrm || ']';
  end;

  -- 06 session + three terms; a term outside the session is rejected
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_sess1;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_sess1, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_t1;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_sess1, 'Second Term', 2, '2027-01-06', '2027-04-02') returning id into v_t2;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_sess1, 'Third Term', 3, '2027-04-26', '2027-07-23') returning id into v_t3;
  begin
    insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
      values (v_org, v_sess1, 'Summer', 4, '2027-08-01', '2027-08-30');
    v_log := v_log || E'\nFAIL 06 term outside session accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 06 term must fall within session [' || sqlerrm || ']';
  end;

  -- 07 term sequence is unique within a session
  begin
    insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
      values (v_org, v_sess1, 'Another First', 1, '2026-09-07', '2026-10-01');
    v_log := v_log || E'\nFAIL 07 duplicate term sequence accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 07 term sequence unique per session [' || sqlerrm || ']';
  end;

  -- 08 is_current is not client-writable
  begin
    update public.academic_terms set is_current = true where id = v_t1;
    v_log := v_log || E'\nFAIL 08 client wrote is_current';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08 is_current only via functions [' || sqlerrm || ']';
  end;

  -- 09 set_current_term makes the term and its session current
  perform public.set_current_term(v_t2);
  select (select count(*) from public.academic_terms where organization_id = v_org and is_current)
       + (select count(*) from public.academic_sessions where organization_id = v_org and is_current)
    into v_n;
  v_ok := exists (select 1 from public.academic_terms where id = v_t2 and is_current)
      and exists (select 1 from public.academic_sessions where id = v_sess1 and is_current);
  v_log := v_log || E'\n' || case when v_ok and v_n = 2 then 'PASS' else 'FAIL' end || ' 09 set_current_term sets term + session';

  -- 10 switching session clears the old session and its current term
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2027/2028', '2027-09-01', '2028-07-31') returning id into v_sess2;
  perform public.set_current_session(v_sess2);
  v_ok := exists (select 1 from public.academic_sessions where id = v_sess2 and is_current)
      and not exists (select 1 from public.academic_sessions where id = v_sess1 and is_current)
      and not exists (select 1 from public.academic_terms where organization_id = v_org and is_current);
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 10 set_current_session clears old session and term';

  -- 11 going back to a term of the old session flips the session back too
  perform public.set_current_term(v_t1);
  v_ok := exists (select 1 from public.academic_sessions where id = v_sess1 and is_current)
      and not exists (select 1 from public.academic_sessions where id = v_sess2 and is_current)
      and exists (select 1 from public.academic_terms where id = v_t1 and is_current);
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 11 current term always belongs to current session';

  -- 12 placements: one arm per student per session; moving updates the row
  insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_s1, v_sess1, v_pry1a);
  insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_s2, v_sess1, v_pry1b);
  begin
    insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_s1, v_sess1, v_pry1b);
    v_log := v_log || E'\nFAIL 12a student placed twice in one session';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 12a one placement per student per session [' || sqlerrm || ']';
  end;
  update public.student_placements set arm_id = v_pry1b where student_id = v_s1 and session_id = v_sess1;
  update public.student_placements set arm_id = v_pry1a where student_id = v_s1 and session_id = v_sess1;
  insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_s1, v_sess2, v_pry1b);
  select count(*) into v_n from public.student_placements where student_id = v_s1;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 12b placement history kept across sessions [' || v_n || ']';

  -- 13 one lead class teacher per arm per session
  insert into public.class_teachers (organization_id, session_id, arm_id, staff_id, is_lead) values (v_org, v_sess1, v_pry1a, v_teacher, true);
  insert into public.class_teachers (organization_id, session_id, arm_id, staff_id, is_lead) values (v_org, v_sess1, v_pry1a, v_teacher2, true);
  select count(*) filter (where is_lead), bool_or(staff_id = v_teacher2 and is_lead) into v_n, v_ok
    from public.class_teachers where session_id = v_sess1 and arm_id = v_pry1a;
  v_log := v_log || E'\n' || case when v_n = 1 and v_ok then 'PASS' else 'FAIL' end || ' 13 new lead demotes previous lead to assistant';

  -- 13b an arm can have a lead with no assistants (Primary 1B: lead only)
  insert into public.class_teachers (organization_id, session_id, arm_id, staff_id, is_lead) values (v_org, v_sess1, v_pry1b, v_teacher3, true);
  v_log := v_log || E'\nPASS 13b lead with no assistants allowed';

  -- 13c at most two assistants: 1A has Ada (demoted) + Kemi; Lola would be a third
  insert into public.class_teachers (organization_id, session_id, arm_id, staff_id, is_lead) values (v_org, v_sess1, v_pry1a, v_teacher3, false);
  begin
    insert into public.class_teachers (organization_id, session_id, arm_id, staff_id, is_lead) values (v_org, v_sess1, v_pry1a, v_teacher4, false);
    v_log := v_log || E'\nFAIL 13c third assistant accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 13c at most two assistants [' || sqlerrm || ']';
  end;

  -- 13d with two assistants, a new lead would push the old lead into a third slot: refused
  begin
    insert into public.class_teachers (organization_id, session_id, arm_id, staff_id, is_lead) values (v_org, v_sess1, v_pry1a, v_teacher4, true);
    v_log := v_log || E'\nFAIL 13d lead change created a third assistant';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 13d lead change can''t overflow assistants [' || sqlerrm || ']';
  end;

  -- 14 structure in use can't be deleted
  begin
    delete from public.classes where id = v_pry1;
    v_log := v_log || E'\nFAIL 14a class with arms deleted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23503' then 'PASS' else 'FAIL' end || ' 14a class with arms cannot be deleted [' || sqlerrm || ']';
  end;
  begin
    delete from public.class_arms where id = v_pry1a;
    v_log := v_log || E'\nFAIL 14b arm with placements deleted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23503' then 'PASS' else 'FAIL' end || ' 14b arm with placements cannot be deleted [' || sqlerrm || ']';
  end;
  delete from public.classes where id = v_jss1;
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 14c unused class can be deleted';

  -- 15 an arm can't be moved to another class
  begin
    update public.class_arms set class_id = v_pry2 where id = v_pry1b;
    v_log := v_log || E'\nFAIL 15 arm moved to another class';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 15 arm cannot change class [' || sqlerrm || ']';
  end;

  -- ── teacher ────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_t_code);

  select count(*) into v_n from public.classes;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 16a teacher reads school''s classes [' || v_n || ']';
  select count(*) into v_n from public.student_placements;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 16b class teacher reads only own pupils'' placements [' || v_n || ']';
  begin
    insert into public.classes (organization_id, section_id, name) values (v_org, v_primary, 'Primary 9');
    v_log := v_log || E'\nFAIL 16c teacher added a class';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16c teacher cannot add classes [' || sqlerrm || ']';
  end;
  begin
    perform public.set_current_term(v_t3);
    v_log := v_log || E'\nFAIL 16d teacher changed the current term';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16d teacher cannot change current term [' || sqlerrm || ']';
  end;
  begin
    perform public.create_standard_structure(v_org);
    v_log := v_log || E'\nFAIL 16e teacher ran the standard structure';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16e teacher cannot set up the structure [' || sqlerrm || ']';
  end;

  -- ── bursar: reads placements, can't change them ───────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bursar","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_b_code);

  select count(*) into v_n from public.student_placements;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 16f bursar reads placements [' || v_n || ']';
  begin
    insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_s2, v_sess2, v_pry1a);
    v_log := v_log || E'\nFAIL 16g bursar placed a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16g bursar cannot place students [' || sqlerrm || ']';
  end;
  update public.student_placements set arm_id = v_pry1b where student_id = v_s1 and session_id = v_sess1;
  get diagnostics v_n = row_count;
  delete from public.student_placements where student_id = v_s2;
  get diagnostics v_rows = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 and v_rows = 0 then 'PASS' else 'FAIL' end || ' 16h bursar cannot move or remove placements';

  -- ── parent ─────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_p_code);

  select count(*) into v_n from public.sections;
  v_log := v_log || E'\n' || case when v_n = 3 then 'PASS' else 'FAIL' end || ' 17a parent reads school structure [' || v_n || ' sections]';
  select count(*) into v_n from public.academic_terms where is_current;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 17b parent sees the current term';
  select count(*) into v_n from public.student_placements;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 17c parent sees only own child''s placements [' || v_n || ']';
  begin
    insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_s2, v_sess2, v_pry1a);
    v_log := v_log || E'\nFAIL 17d parent placed a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 17d parent cannot place students [' || sqlerrm || ']';
  end;
  update public.student_placements set arm_id = v_pry1b where student_id = v_s1 and session_id = v_sess1;
  get diagnostics v_n = row_count;
  delete from public.student_placements where student_id = v_s1;
  get diagnostics v_rows = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 and v_rows = 0 then 'PASS' else 'FAIL' end || ' 17e parent cannot move or remove own child''s placement';

  -- ── student ────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_student","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_s_code);
  select count(*) into v_n from public.student_placements;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 18 student sees only own placements [' || v_n || ']';
  begin
    insert into public.student_placements (organization_id, student_id, session_id, arm_id) values (v_org, v_s2, v_sess2, v_pry1a);
    v_log := v_log || E'\nFAIL 18b student placed a student';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 18b student cannot place students [' || sqlerrm || ']';
  end;
  update public.student_placements set arm_id = v_pry1b where student_id = v_s1 and session_id = v_sess1;
  get diagnostics v_n = row_count;
  delete from public.student_placements where student_id = v_s1;
  get diagnostics v_rows = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 and v_rows = 0 then 'PASS' else 'FAIL' end || ' 18c student cannot move or remove own placement';

  -- 18d nothing above changed the placements: Chidi is still in 1A for 2026/2027
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select arm_id into v_arm from public.student_placements where student_id = v_s1 and session_id = v_sess1;
  select count(*) into v_n from public.student_placements where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_arm = v_pry1a and v_n = 3 then 'PASS' else 'FAIL' end || ' 18d placements unchanged after bursar, parent and student attempts';

  -- ── other school's owner ───────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.classes;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 19a other school sees only its own classes [' || v_n || ']';
  select count(*) into v_n from public.student_placements;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 19b other school sees no School A placements [' || v_n || ']';
  begin
    perform public.set_current_session(v_sess2);
    v_log := v_log || E'\nFAIL 19c other school changed School A''s session';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 19c other school cannot change School A''s session [' || sqlerrm || ']';
  end;

  -- ── platform admin, then suspension ────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.classes;
  v_log := v_log || E'\n' || case when v_n = 18 then 'PASS' else 'FAIL' end || ' 20 platform admin reads classes in every school [' || v_n || ']';
  perform public.set_organization_status(v_org, 'suspended');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.sections;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 21 suspended school: parent sees no structure [' || v_n || ']';

  -- 22 anon has no access
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform count(*) from public.classes;
    v_log := v_log || E'\nFAIL 22 anon read classes';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 22 anon cannot read classes [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('03_academic_structure', v_log);
end;
$test$;

-- ── 04_subjects_access_test.sql ──
do $test$
declare
  v_log  text := '';
  v_n    int;
  v_ok   boolean;
  v_org  uuid;  v_claim  text;
  v_org2 uuid;  v_claim2 text;
  -- staff
  v_ada uuid;   v_ada_code  text;   -- Mathematics, JSS 1A
  v_bisi uuid;  v_bisi_code text;   -- French (optional), JSS 1A
  v_chuka uuid; v_chuka_code text;  -- class teacher, JSS 1B
  v_dele uuid;  v_dele_code text;   -- no classes
  v_bayo uuid;  v_bayo_code text;   -- bursar
  -- structure
  v_jss1 uuid;  v_ss1 uuid;
  v_jss1a uuid; v_jss1b uuid; v_ss1a uuid;
  v_jss1c uuid; v_ss1b uuid;  -- created after the standard subjects
  v_sess1 uuid; v_sess2 uuid; v_term1 uuid;
  v_maths uuid; v_french uuid; v_physics uuid; v_dataproc uuid;
  -- students / parents
  v_s1 uuid; v_s2 uuid; v_s3 uuid; v_s4 uuid;
  v_p1 uuid; v_p3 uuid;
  v_p1_code text; v_s1_code text;
  v_r record;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup ──────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('School A', 'SCA') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('School B', 'SCB') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bimbo', 'Owner');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');

  -- structure, session, term
  perform public.create_standard_structure(v_org);
  select id into v_jss1 from public.classes where organization_id = v_org and name = 'JSS 1';
  select id into v_ss1  from public.classes where organization_id = v_org and name = 'SS 1';
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'A') returning id into v_jss1a;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'B') returning id into v_jss1b;
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_ss1,  'A') returning id into v_ss1a;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2026/2027', '2026-09-01', '2027-07-31') returning id into v_sess1;
  insert into public.academic_sessions (organization_id, name, starts_on, ends_on)
    values (v_org, '2027/2028', '2027-09-01', '2028-07-31') returning id into v_sess2;
  insert into public.academic_terms (organization_id, session_id, name, sequence, starts_on, ends_on)
    values (v_org, v_sess1, 'First Term', 1, '2026-09-07', '2026-12-18') returning id into v_term1;
  perform public.set_current_term(v_term1);

  -- 00a standard subjects: 41 subjects, and the standard curriculum on every existing arm
  v_n := public.create_standard_subjects(v_org);
  v_ok := v_n = 41
      and (select count(*) from public.arm_subjects where organization_id = v_org) = 58
      and (select count(*) from public.arm_subjects where arm_id = v_jss1a) = 17
      and (select count(*) from public.arm_subjects where arm_id = v_jss1a and is_compulsory) = 14
      and (select count(*) from public.arm_subjects where arm_id = v_ss1a) = 24
      and (select count(*) from public.arm_subjects where arm_id = v_ss1a and is_compulsory) = 3;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 00a standard subjects + curriculum on existing arms [' || v_n || ' subjects]';

  -- 00b only for a school with no subjects
  begin
    perform public.create_standard_subjects(v_org);
    v_log := v_log || E'\nFAIL 00b standard subjects added twice';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%already has subjects%' then 'PASS' else 'FAIL' end || ' 00b standard subjects only for a new school [' || sqlerrm || ']';
  end;

  select id into v_maths    from public.subjects where organization_id = v_org and name = 'Mathematics';
  select id into v_french   from public.subjects where organization_id = v_org and name = 'French';
  select id into v_physics  from public.subjects where organization_id = v_org and name = 'Physics';
  select id into v_dataproc from public.subjects where organization_id = v_org and name = 'Data Processing';

  -- 00c copy_arm_subjects: a new JSS 1C gets JSS 1A's list; copying again adds nothing
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_jss1, 'C') returning id into v_jss1c;
  v_n := public.copy_arm_subjects(v_jss1a, v_jss1c);
  v_ok := v_n = 17 and public.copy_arm_subjects(v_jss1a, v_jss1c) = 0;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 00c copy_arm_subjects copies once [' || v_n || ' added]';

  -- 00d an Arts arm: standard SS list, then the school tailors it (no sciences)
  insert into public.class_arms (organization_id, class_id, name) values (v_org, v_ss1, 'Arts') returning id into v_ss1b;
  v_n := public.apply_standard_curriculum(v_ss1b);
  delete from public.arm_subjects
    where arm_id = v_ss1b
      and subject_id in (select id from public.subjects where organization_id = v_org and name in ('Physics', 'Chemistry', 'Biology'));
  update public.arm_subjects set is_compulsory = true
    where arm_id = v_ss1b
      and subject_id in (select id from public.subjects where organization_id = v_org and name in ('Literature in English', 'Government'));
  v_ok := v_n = 24
      and (select count(*) from public.arm_subjects where arm_id = v_ss1b) = 21
      and (select count(*) from public.arm_subjects where arm_id = v_ss1b and is_compulsory) = 5
      and (select count(*) from public.arm_subjects where arm_id = v_ss1a) = 24;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 00d arms of one class can have different subjects (SS 1 Arts vs SS 1A)';

  -- 01 subject names and codes are unique per school (case-insensitive)
  begin
    insert into public.subjects (organization_id, name) values (v_org, 'mathematics');
    v_log := v_log || E'\nFAIL 01a duplicate subject name accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 01a subject name unique per school [' || sqlerrm || ']';
  end;
  begin
    insert into public.subjects (organization_id, name, code) values (v_org, 'Maths Two', 'mth');
    v_log := v_log || E'\nFAIL 01b duplicate subject code accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 01b subject code unique per school [' || sqlerrm || ']';
  end;

  -- 02 code format
  begin
    insert into public.subjects (organization_id, name, code) values (v_org, 'Odd Code', 'M-1');
    v_log := v_log || E'\nFAIL 02 bad subject code accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 02 subject code format checked [' || sqlerrm || ']';
  end;

  -- people
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada',   'Maths')   returning id into v_ada;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Bisi',  'French')  returning id into v_bisi;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Chuka', 'Class')   returning id into v_chuka;
  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Dele',  'Nothing') returning id into v_dele;
  insert into public.staff (organization_id, first_name, last_name, staff_type) values (v_org, 'Bayo', 'Bursar', 'non_teaching') returning id into v_bayo;
  v_ada_code   := public.invite_staff(v_ada);
  v_bisi_code  := public.invite_staff(v_bisi);
  v_chuka_code := public.invite_staff(v_chuka);
  v_dele_code  := public.invite_staff(v_dele);
  v_bayo_code  := public.invite_staff(v_bayo, 'bursar');

  insert into public.students (organization_id, first_name, last_name) values (v_org, 'S1', 'JSS1A') returning id into v_s1;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'S2', 'JSS1A') returning id into v_s2;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'S3', 'JSS1B') returning id into v_s3;
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'S4', 'SS1A')  returning id into v_s4;
  insert into public.student_placements (organization_id, student_id, session_id, arm_id) values
    (v_org, v_s1, v_sess1, v_jss1a), (v_org, v_s2, v_sess1, v_jss1a),
    (v_org, v_s3, v_sess1, v_jss1b), (v_org, v_s4, v_sess1, v_ss1a);
  insert into public.parents (organization_id, first_name, last_name, phone) values (v_org, 'P1', 'OfS1', '0801000001') returning id into v_p1;
  insert into public.parents (organization_id, first_name, last_name, phone) values (v_org, 'P3', 'OfS3', '0801000003') returning id into v_p3;
  insert into public.student_parents (organization_id, student_id, parent_id, relationship, is_primary_contact) values
    (v_org, v_s1, v_p1, 'mother', true), (v_org, v_s3, v_p3, 'father', true);
  v_p1_code := public.invite_parent(v_p1);
  v_s1_code := public.invite_student(v_s1);

  -- 03 assignments: Ada → Maths JSS 1A, Bisi → French JSS 1A, Chuka → class teacher JSS 1B
  insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id) values
    (v_org, v_sess1, v_jss1a, v_maths,  v_ada),
    (v_org, v_sess1, v_jss1a, v_french, v_bisi);
  insert into public.class_teachers (organization_id, session_id, arm_id, staff_id, is_lead) values (v_org, v_sess1, v_jss1b, v_chuka, true);
  v_log := v_log || E'\nPASS 03 teaching assignments created';

  -- 04 one teacher per subject per arm per session
  begin
    insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id) values (v_org, v_sess1, v_jss1a, v_maths, v_dele);
    v_log := v_log || E'\nFAIL 04 second Maths teacher for JSS 1A accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 04 one teacher per subject per arm per session [' || sqlerrm || ']';
  end;

  -- 05 can't assign a subject the class doesn't offer
  begin
    insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id) values (v_org, v_sess1, v_jss1a, v_physics, v_dele);
    v_log := v_log || E'\nFAIL 05 Physics assigned to JSS 1A';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 05 subject must be on the arm''s curriculum [' || sqlerrm || ']';
  end;
  begin
    insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id) values (v_org, v_sess1, v_ss1b, v_physics, v_dele);
    v_log := v_log || E'\nFAIL 05b Physics assigned to the Arts arm';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 05b Arts arm doesn''t take Physics even though SS 1A does [' || sqlerrm || ']';
  end;
  insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id) values (v_org, v_sess1, v_ss1a, v_physics, v_dele);
  delete from public.teaching_assignments where session_id = v_sess1 and arm_id = v_ss1a and subject_id = v_physics;
  v_log := v_log || E'\nPASS 05c Physics can be assigned to the science arm';

  -- 06 changing the teacher updates the row
  update public.teaching_assignments set staff_id = v_dele where session_id = v_sess1 and arm_id = v_jss1a and subject_id = v_maths;
  update public.teaching_assignments set staff_id = v_ada  where session_id = v_sess1 and arm_id = v_jss1a and subject_id = v_maths;
  select count(*) into v_n from public.teaching_assignments where session_id = v_sess1 and arm_id = v_jss1a and subject_id = v_maths and staff_id = v_ada;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 06 teacher can be changed';

  -- 07 electives
  insert into public.student_subjects (organization_id, student_id, session_id, subject_id) values (v_org, v_s1, v_sess1, v_french);
  insert into public.student_subjects (organization_id, student_id, session_id, subject_id) values (v_org, v_s4, v_sess1, v_physics);
  v_log := v_log || E'\nPASS 07a optional subjects enrolled (S1 French, S4 Physics)';
  begin
    insert into public.student_subjects (organization_id, student_id, session_id, subject_id) values (v_org, v_s2, v_sess1, v_maths);
    v_log := v_log || E'\nFAIL 07b compulsory subject enrolled';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 07b compulsory subjects aren''t enrolled [' || sqlerrm || ']';
  end;
  begin
    insert into public.student_subjects (organization_id, student_id, session_id, subject_id) values (v_org, v_s3, v_sess1, v_physics);
    v_log := v_log || E'\nFAIL 07c subject not offered by class enrolled';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 07c only subjects the arm offers [' || sqlerrm || ']';
  end;
  begin
    insert into public.student_subjects (organization_id, student_id, session_id, subject_id) values (v_org, v_s1, v_sess2, v_french);
    v_log := v_log || E'\nFAIL 07d enrolled in a session without a placement';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 07d student must be placed that session [' || sqlerrm || ']';
  end;

  -- 07e session_readiness for 2026/2027: 1 term, 4 placed, 3 arms with students,
  --     2 without a lead class teacher (JSS 1A, SS 1A), 56 arm subjects without a teacher
  --     (JSS 1A 17-2, JSS 1B 17, SS 1A 24)
  select * into v_r from public.session_readiness(v_sess1);
  v_log := v_log || E'\n' || case when v_r.terms = 1 and v_r.students_placed = 4 and v_r.active_students_not_placed = 0
        and v_r.arms_with_students = 3 and v_r.arms_without_lead_teacher = 2 and v_r.subjects_without_teacher = 56
        then 'PASS' else 'FAIL' end || ' 07e session_readiness reports what''s missing ['
        || v_r.terms || '/' || v_r.students_placed || '/' || v_r.active_students_not_placed || '/'
        || v_r.arms_with_students || '/' || v_r.arms_without_lead_teacher || '/' || v_r.subjects_without_teacher || ']';

  -- ── Ada: compulsory Maths in JSS 1A → S1, S2 ───────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_ada","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_ada_code);
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 08a compulsory-subject teacher sees the whole arm [' || v_n || ']';
  select count(*) into v_n from public.parents;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 08b and only those students'' parents [' || v_n || ']';
  select count(*) into v_n from public.parent_private_details;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 08b2 but not the parents'' private details [' || v_n || ']';
  select count(*) into v_n from public.student_placements;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 08c and only their placements [' || v_n || ']';
  select count(*) into v_n from public.student_private_details;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 08c2 and their private details while teaching them [' || v_n || ']';
  begin
    insert into public.teaching_assignments (organization_id, session_id, arm_id, subject_id, staff_id) values (v_org, v_sess1, v_jss1b, v_maths, v_ada);
    v_log := v_log || E'\nFAIL 08d teacher assigned themselves';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08d teachers can''t make assignments [' || sqlerrm || ']';
  end;
  begin
    perform public.create_standard_subjects(v_org2);
    v_log := v_log || E'\nFAIL 08e teacher ran standard subjects elsewhere';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08e teachers can''t set up subjects [' || sqlerrm || ']';
  end;
  begin
    perform public.copy_arm_subjects(v_jss1a, v_jss1b);
    v_log := v_log || E'\nFAIL 08f teacher copied arm subjects';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08f teachers can''t copy or apply curricula [' || sqlerrm || ']';
  end;
  begin
    perform public.copy_assignments_forward(v_sess1, v_sess2);
    v_log := v_log || E'\nFAIL 08g teacher copied assignments forward';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 08g teachers can''t copy assignments or check readiness [' || sqlerrm || ']';
  end;

  -- ── Bisi: optional French in JSS 1A → only S1 ──────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bisi","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bisi_code);
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 09a optional-subject teacher sees only students taking it [' || v_n || ']';
  select count(*) into v_n from public.student_subjects;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 09b and their electives [' || v_n || ']';

  -- ── Chuka: class teacher of JSS 1B → S3 ────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_chuka","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_chuka_code);
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 10a class teacher sees their arm [' || v_n || ']';
  select count(*) into v_n from public.parents;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 10b class teacher sees their pupils'' parents [' || v_n || ']';

  -- ── Dele: no classes → nobody ──────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_dele","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_dele_code);
  select (select count(*) from public.students) + (select count(*) from public.parents) into v_n;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 11 teacher with no classes sees no students or parents [' || v_n || ']';
  select count(*) into v_n from public.subjects;
  v_log := v_log || E'\n' || case when v_n = 41 then 'PASS' else 'FAIL' end || ' 11b but still reads the subject list [' || v_n || ']';

  -- ── Bayo: bursar → whole school ────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_bayo","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_bayo_code);
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 4 then 'PASS' else 'FAIL' end || ' 12 bursar still sees every student [' || v_n || ']';

  -- ── parent P1 and student S1 ───────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_p1_code);
  select count(*) into v_n from public.teaching_assignments;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 13a parent sees who teaches what [' || v_n || ']';
  select count(*) into v_n from public.student_subjects;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 13b parent sees only own child''s electives [' || v_n || ']';
  begin
    insert into public.student_subjects (organization_id, student_id, session_id, subject_id)
      values (v_org, v_s1, v_sess1, (select id from public.subjects where organization_id = v_org and name = 'Christian Religious Studies'));
    v_log := v_log || E'\nFAIL 13c parent enrolled their child';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 13c parents can''t enrol subjects [' || sqlerrm || ']';
  end;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_student","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_s1_code);
  select count(*) into v_n from public.student_subjects;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 14 student sees own electives [' || v_n || ']';

  -- ── other school ───────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select (select count(*) from public.subjects) + (select count(*) from public.teaching_assignments) into v_n;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 15 other school sees none of School A''s subjects [' || v_n || ']';

  -- ── owner: deletes, then a new session ─────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    delete from public.subjects where id = v_maths;
    v_log := v_log || E'\nFAIL 16a taught subject deleted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23503' then 'PASS' else 'FAIL' end || ' 16a a subject with assignments can''t be deleted [' || sqlerrm || ']';
  end;
  -- Data Processing is on SS 1A and SS 1 Arts but taught by nobody: 96 links → 94
  delete from public.subjects where id = v_dataproc;
  select count(*) into v_n from public.arm_subjects where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_n = 94 then 'PASS' else 'FAIL' end || ' 16b untaught subject deleted with its curriculum links [' || v_n || ' left]';

  -- 16c copy assignments into 2027/2028: Bisi has exited, so only Ada's Maths + Chuka's class
  --     copy across; a second run copies nothing; readiness for 2027/2028 reflects it
  update public.staff set status = 'exited' where id = v_bisi;
  select * into v_r from public.copy_assignments_forward(v_sess1, v_sess2);
  v_ok := v_r.class_teachers_copied = 1 and v_r.subject_teachers_copied = 1;
  select * into v_r from public.copy_assignments_forward(v_sess1, v_sess2);
  v_ok := v_ok and v_r.class_teachers_copied = 0 and v_r.subject_teachers_copied = 0
      and exists (select 1 from public.teaching_assignments where session_id = v_sess2 and arm_id = v_jss1a and subject_id = v_maths and staff_id = v_ada)
      and exists (select 1 from public.class_teachers where session_id = v_sess2 and arm_id = v_jss1b and staff_id = v_chuka and is_lead)
      and not exists (select 1 from public.teaching_assignments where session_id = v_sess2 and staff_id = v_bisi);
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 16c copy_assignments_forward copies once, skips exited staff';
  select * into v_r from public.session_readiness(v_sess2);
  v_log := v_log || E'\n' || case when v_r.terms = 0 and v_r.students_placed = 0 and v_r.active_students_not_placed = 4
        then 'PASS' else 'FAIL' end || ' 16d readiness flags an unprepared session [' || v_r.terms || ' terms, ' || v_r.active_students_not_placed || ' not placed]';

  -- 17 after the school moves to 2027/2028, Ada becomes a PAST teacher of S1 and S2:
  --    she still sees their profiles (names, for old scores), but no longer their
  --    private details or parents
  perform public.set_current_session(v_sess2);
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_ada","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 17a past teacher still sees former students'' profiles [' || v_n || ']';
  select (select count(*) from public.student_private_details) + (select count(*) from public.parents) into v_n;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 17b but not their private details or parents [' || v_n || ']';
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_dele","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.students;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 17c a teacher who never taught them sees nobody [' || v_n || ']';

  -- 18 platform admin reads every school's subjects
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.subjects;
  v_log := v_log || E'\n' || case when v_n = 40 then 'PASS' else 'FAIL' end || ' 18 platform admin reads subjects in every school [' || v_n || ']';

  -- 19 anon has no access
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform count(*) from public.subjects;
    v_log := v_log || E'\nFAIL 19 anon read subjects';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 19 anon cannot read subjects [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('04_subjects', v_log);
end;
$test$;

-- ── 05_grading_setup_access_test.sql ──
do $test$
declare
  v_log  text := '';
  v_n    int;
  v_ok   boolean;
  v_txt  text;
  v_org  uuid;  v_claim  text;
  v_org2 uuid;  v_claim2 text;
  v_nursery uuid; v_secondary uuid;
  v_nur1a uuid; v_pry1a uuid; v_jss1a uuid;
  v_teacher uuid; v_t_code text;
  v_s1 uuid; v_p1 uuid; v_p_code text;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup ──────────────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org,  v_claim  from public.create_organization('School A', 'SCA') c;
  select c.organization_id, c.owner_claim_code into v_org2, v_claim2 from public.create_organization('School B', 'SCB') c;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim2, 'Bimbo', 'Owner');

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
  perform public.create_standard_structure(v_org);
  select id into v_nursery   from public.sections where organization_id = v_org and name = 'Nursery';
  select id into v_secondary from public.sections where organization_id = v_org and name = 'Secondary';
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'Nursery 1' returning id into v_nur1a;
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'Primary 1' returning id into v_pry1a;
  insert into public.class_arms (organization_id, class_id, name)
    select v_org, id, 'A' from public.classes where organization_id = v_org and name = 'JSS 1' returning id into v_jss1a;

  insert into public.staff (organization_id, first_name, last_name) values (v_org, 'Ada', 'Teacher') returning id into v_teacher;
  v_t_code := public.invite_staff(v_teacher);
  insert into public.students (organization_id, first_name, last_name) values (v_org, 'Chidi', 'Pupil') returning id into v_s1;
  insert into public.parents (organization_id, first_name, last_name, phone) values (v_org, 'Ngozi', 'Pupil', '0801111111') returning id into v_p1;
  insert into public.student_parents (organization_id, student_id, parent_id, relationship, is_primary_contact) values (v_org, v_s1, v_p1, 'mother', true);
  v_p_code := public.invite_parent(v_p1);

  -- 00a standard setup: the school's columns + A–F, Secondary's own WAEC boundaries only
  perform public.create_standard_grading(v_org);
  v_ok := (select count(*) from public.score_columns    where organization_id = v_org and section_id is null) = 3
      and (select sum(max_score) from public.score_columns where organization_id = v_org and section_id is null) = 100
      and (select count(*) from public.grade_boundaries where organization_id = v_org and section_id is null) = 6
      and (select count(*) from public.score_columns    where section_id = v_secondary) = 0
      and (select count(*) from public.grade_boundaries where section_id = v_secondary) = 9;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 00a standard grading setup created';

  -- 00b only for a new school
  begin
    perform public.create_standard_grading(v_org);
    v_log := v_log || E'\nFAIL 00b standard grading created twice';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%already has a grading setup%' then 'PASS' else 'FAIL' end || ' 00b standard setup only for a new school [' || sqlerrm || ']';
  end;

  -- 01 fall-back: JSS 1A uses the school's columns but Secondary's grade boundaries;
  --    Primary 1A uses the school's for both
  select string_agg(name, ',' order by sort_order) into v_txt from public.score_columns_for_arm(v_jss1a);
  v_ok := v_txt = 'CA 1,CA 2,Exam'
      and (select count(*) from public.grade_boundaries_for_arm(v_jss1a)) = 9
      and (select count(*) from public.grade_boundaries_for_arm(v_pry1a)) = 6;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 01 columns and boundaries each fall back to the school''s';

  -- 02 grades come from boundaries, including decimals between them
  v_txt := (public.grade_for(v_jss1a, 74.5)).grade || ',' || (public.grade_for(v_jss1a, 75)).grade || ','
        || (public.grade_for(v_jss1a, 39.99)).grade || ',' || (public.grade_for(v_pry1a, 69.99)).grade || ','
        || (public.grade_for(v_pry1a, 0)).grade || ',' || (public.grade_for(v_pry1a, 100)).grade;
  v_log := v_log || E'\n' || case when v_txt = 'B2,A1,F9,B,F,A' then 'PASS' else 'FAIL' end || ' 02 grades come from boundaries [' || coalesce(v_txt, 'null') || ']';
  v_ok := not (public.grade_for(v_jss1a, 30)).is_pass and (public.grade_for(v_jss1a, 45)).is_pass;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 02b pass/fail flag comes with the grade';

  -- 03 Nursery gets its own single column; it still uses the school's grade boundaries
  insert into public.score_columns (organization_id, section_id, name, max_score) values (v_org, v_nursery, 'Observation', 100);
  select string_agg(name, ',') into v_txt from public.score_columns_for_arm(v_nur1a);
  v_ok := v_txt = 'Observation'
      and (public.grade_for(v_nur1a, 72)).grade = 'A'
      and cardinality(public.grading_problems(v_org, v_nursery)) = 0
      and cardinality(public.grading_problems(v_org)) = 0
      and cardinality(public.grading_problems(v_org2)) = 2;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 03 a section can override just its columns; problems reported for an unset school';

  -- 04 uniqueness is per set (the school's, or one section's)
  begin
    insert into public.score_columns (organization_id, name, max_score) values (v_org, 'ca 1', 10);
    v_log := v_log || E'\nFAIL 04a duplicate column in the school''s set accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 04a column names unique within a set [' || sqlerrm || ']';
  end;
  insert into public.score_columns (organization_id, section_id, name, max_score) values (v_org, v_nursery, 'CA 1', 10);
  v_log := v_log || E'\nPASS 04b the same column name is fine in another set (Nursery CA 1)';
  begin
    insert into public.grade_boundaries (organization_id, section_id, grade, min_percent) values (v_org, v_secondary, 'X', 75);
    v_log := v_log || E'\nFAIL 04c duplicate starting point accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23505' then 'PASS' else 'FAIL' end || ' 04c one grade per starting point within a set [' || sqlerrm || ']';
  end;

  -- 05 validation
  begin
    insert into public.grade_boundaries (organization_id, grade, min_percent) values (v_org, 'Z', 100);
    v_log := v_log || E'\nFAIL 05a boundary at 100% accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 05a boundaries must be below 100% [' || sqlerrm || ']';
  end;
  begin
    insert into public.score_columns (organization_id, name, max_score) values (v_org, 'Project', 0);
    v_log := v_log || E'\nFAIL 05b zero max score accepted';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '23514' then 'PASS' else 'FAIL' end || ' 05b max score must be positive [' || sqlerrm || ']';
  end;
  insert into public.score_columns (organization_id, name, max_score, sort_order) values (v_org, 'Project', 12.5, 4);
  v_log := v_log || E'\nPASS 05c decimal max scores allowed (12.5)';

  -- ── teacher: reads the setup, can't change it ──────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_t_code);
  select count(*) into v_n from public.score_columns;
  v_log := v_log || E'\n' || case when v_n = 6 then 'PASS' else 'FAIL' end || ' 06a teacher reads the grading setup [' || v_n || ' score columns]';
  begin
    insert into public.score_columns (organization_id, name, max_score) values (v_org, 'Quiz', 5);
    v_log := v_log || E'\nFAIL 06b teacher added a score column';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06b teachers can''t change the setup [' || sqlerrm || ']';
  end;
  update public.grade_boundaries set min_percent = 50 where organization_id = v_org and section_id is null and grade = 'A';
  get diagnostics v_n = row_count;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 06c teachers can''t edit grade boundaries';
  begin
    perform public.create_standard_grading(v_org2);
    v_log := v_log || E'\nFAIL 06d teacher set up another school';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 06d teachers can''t run the standard setup [' || sqlerrm || ']';
  end;

  -- ── parent: reads grade boundaries (for the report card) ─
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_parent","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_claim_code(v_p_code);
  select count(*) into v_n from public.grade_boundaries;
  v_log := v_log || E'\n' || case when v_n = 15 then 'PASS' else 'FAIL' end || ' 07 parent reads grade boundaries [' || v_n || ']';

  -- ── other school ───────────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_b","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select (select count(*) from public.score_columns) + (select count(*) from public.grade_boundaries) into v_n;
  v_log := v_log || E'\n' || case when v_n = 0 then 'PASS' else 'FAIL' end || ' 08 other school sees none of School A''s setup [' || v_n || ']';

  -- ── owner: removing Secondary's boundaries falls back to the school's ─
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  delete from public.grade_boundaries where section_id = v_secondary;
  v_ok := (public.grade_for(v_jss1a, 74.5)).grade = 'A'
      and (select count(*) from public.grade_boundaries_for_arm(v_jss1a)) = 6;
  v_log := v_log || E'\n' || case when v_ok then 'PASS' else 'FAIL' end || ' 09 without its own boundaries, Secondary uses the school''s';

  -- 10 anon has no access
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform count(*) from public.grade_boundaries;
    v_log := v_log || E'\nFAIL 10 anon read grade boundaries';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 10 anon cannot read grade boundaries [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('05_grading_setup', v_log);
end;
$test$;

-- ── 06_owner_staff_record_test.sql ──
do $test$
declare
  v_log    text := '';
  v_n      int;
  v_org    uuid;
  v_claim  text;
  v_member public.organization_members;
  v_staff  public.staff;
  v_ada    uuid;
  v_t_code text;
  v_owner2_code text;
  v_owner3_code text;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: one school ──────────────────────────────────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.organization_id, c.owner_claim_code into v_org, v_claim from public.create_organization('Test School', 'TST') c;

  -- 01 an owner code needs a first and last name; blanks don't count
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.redeem_claim_code(v_claim);
    v_log := v_log || E'\nFAIL 01a owner redeemed without a name';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 01a owner code needs a name [' || sqlerrm || ']';
  end;
  begin
    perform public.redeem_claim_code(v_claim, '  ', 'Owner');
    v_log := v_log || E'\nFAIL 01b owner redeemed with a blank first name';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 01b blank name rejected [' || sqlerrm || ']';
  end;

  -- 02 the same code still works once a name is given; the staff record is linked
  v_member := public.redeem_claim_code(v_claim, ' Olu ', ' Owner ', 'olu@school.test', '0801234567');
  select s.* into v_staff from public.staff s where s.member_id = v_member.id;
  v_log := v_log || E'\n' || case when v_member.status = 'active' and v_member.role = 'owner'
        and v_staff.first_name = 'Olu' and v_staff.last_name = 'Owner'
        and v_staff.email = 'olu@school.test' and v_staff.phone = '0801234567'
        and v_staff.job_title = 'Owner' and v_staff.staff_type = 'non_teaching'
        and v_staff.staff_number = 'TST/STF/0001'
        then 'PASS' else 'FAIL' end || ' 02 owner redeems and gets a linked staff record [' || coalesce(v_staff.staff_number, 'none') || ']';

  -- 03 the record has its private details row, like every staff member
  select count(*) into v_n from public.staff_private_details where staff_id = v_staff.id;
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 03 owner''s private details row created [' || v_n || ']';

  -- 04 the owner edits their own record like any other
  perform public.update_staff(v_staff.id, 'Olu', 'Owner', null, '', null, '0801234567', 'olu@school.test', null, null,
                              'Proprietor', 'teaching', 'active', null, null, null, null);
  select count(*) into v_n from public.staff s
    where s.id = v_staff.id and s.job_title = 'Proprietor' and s.staff_type = 'teaching' and s.staff_number = 'TST/STF/0001';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 04 owner can edit own staff record';

  -- 05 a used owner code is still rejected, name or not
  begin
    perform public.redeem_claim_code(v_claim, 'Olu', 'Owner');
    v_log := v_log || E'\nFAIL 05 owner code reused';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%invalid or has already been used%' then 'PASS' else 'FAIL' end || ' 05 used owner code rejected [' || sqlerrm || ']';
  end;

  -- 06 a teacher code needs no name and makes no extra staff record
  v_ada := (public.create_staff(p_organization_id => v_org, p_first_name => 'Ada', p_last_name => 'Teacher')).id;
  v_t_code := public.invite_staff(v_ada);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_t_code);

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select count(*) into v_n from public.staff where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_member.role = 'teacher' and v_member.status = 'active' and v_n = 2
        then 'PASS' else 'FAIL' end || ' 06 teacher code needs no name, no extra staff record [' || v_n || ' staff]';

  -- 07 a second owner who is already on staff keeps their one record
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  insert into public.organization_members (organization_id, role) values (v_org, 'owner') returning claim_code into v_owner2_code;
  insert into public.organization_members (organization_id, role) values (v_org, 'owner') returning claim_code into v_owner3_code;

  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_teacher","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_owner2_code);
  select count(*) into v_n from public.staff where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_member.role = 'owner' and v_n = 2
        then 'PASS' else 'FAIL' end || ' 07 existing staff member becomes owner without a second record [' || v_n || ' staff]';

  -- 08 a second owner who is new to the school gets their own record
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_owner_2","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_member := public.redeem_claim_code(v_owner3_code, 'Bimbo', 'Partner');
  select s.* into v_staff from public.staff s where s.member_id = v_member.id;
  select count(*) into v_n from public.staff where organization_id = v_org;
  v_log := v_log || E'\n' || case when v_n = 3 and v_staff.last_name = 'Partner' and v_staff.staff_number = 'TST/STF/0003'
        then 'PASS' else 'FAIL' end || ' 08 new co-owner gets own staff record [' || v_n || ' staff, ' || coalesce(v_staff.staff_number, 'none') || ']';

  -- 09 anon cannot redeem
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform public.redeem_claim_code('ABCD2345', 'Anon', 'User');
    v_log := v_log || E'\nFAIL 09 anon called redeem_claim_code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 09 anon cannot redeem [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('06_owner_staff_record_test', v_log);
end;
$test$;

-- ── 07_platform_invites_access_test.sql ──
do $test$
declare
  v_log     text := '';
  v_n       int;
  v_code    text;
  v_code2   text;
  v_invite  uuid;
  v_invite2 uuid;
  v_expires timestamptz;
  v_admin   public.platform_admins;
  v_status  text;
begin
  begin
  -- The test platform admin exists only inside this test; it's rolled back
  -- with everything else, so the live database needs no fake admin.
  execute 'reset role';
  insert into public.platform_admins (clerk_user_id, full_name)
  values ('user_dummy_platform_admin', 'Dummy Platform Admin')
  on conflict (clerk_user_id) do nothing;

  -- ── setup: the dummy platform admin creates a code ─────────
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.invite_id, c.code, c.expires_at into v_invite, v_code, v_expires
  from public.create_platform_invite(' Amina, support ') c;

  -- 01 a code is 12 allowed characters, expires in 7 days, and only its hash is stored
  execute 'reset role';
  select count(*) into v_n from private.platform_invite_codes c
    where c.id = v_invite and c.code_hash = private.platform_code_hash(v_code)
      and c.code_hash <> v_code and c.code_hint = right(v_code, 4) and c.note = 'Amina, support';
  v_log := v_log || E'\n' || case when v_code ~ '^[A-HJ-NP-Z2-9]{12}$' and v_n = 1
        and v_expires between now() + interval '6 days 23 hours' and now() + interval '7 days 1 minute'
        then 'PASS' else 'FAIL' end || ' 01 code shape, 7-day expiry, hash stored not the code';

  -- 02 a non-admin can't create, list or cancel codes
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.create_platform_invite('sneaky');
    v_log := v_log || E'\nFAIL 02a non-admin created a code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 02a non-admin cannot create [' || sqlerrm || ']';
  end;
  begin
    perform public.list_platform_invites();
    v_log := v_log || E'\nFAIL 02b non-admin listed codes';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 02b non-admin cannot list [' || sqlerrm || ']';
  end;
  begin
    perform public.revoke_platform_invite(v_invite);
    v_log := v_log || E'\nFAIL 02c non-admin cancelled a code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 02c non-admin cannot cancel [' || sqlerrm || ']';
  end;

  -- 03 clients can't read the code tables directly
  begin
    select count(*) into v_n from private.platform_invite_codes;
    v_log := v_log || E'\nFAIL 03 authenticated read private.platform_invite_codes';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 03 code table not readable [' || sqlerrm || ']';
  end;

  -- 04 a name is required; the code still works afterwards
  begin
    perform public.redeem_platform_invite(v_code, '   ');
    v_log := v_log || E'\nFAIL 04 redeemed without a name';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '22023' then 'PASS' else 'FAIL' end || ' 04 name required [' || sqlerrm || ']';
  end;

  -- 05 a wrong code returns null and counts as an attempt
  v_admin := public.redeem_platform_invite('WRONG-CODE-0000', 'New Person');
  execute 'reset role';
  select count(*) into v_n from private.platform_invite_attempts where clerk_user_id = 'test_newcomer';
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id is null and v_n = 1
        then 'PASS' else 'FAIL' end || ' 05 wrong code → null, attempt recorded [' || v_n || ']';

  -- 06 the right code, typed loosely, makes the caller a platform admin
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_invite(
    lower(substr(v_code, 1, 4) || '-' || substr(v_code, 5, 4) || ' ' || substr(v_code, 9, 4)),
    ' New Person ', ' new@hamrash.test ');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id = 'test_newcomer' and v_admin.is_active
        and v_admin.full_name = 'New Person' and v_admin.email = 'new@hamrash.test'
        then 'PASS' else 'FAIL' end || ' 06 code redeemed, caller is now a platform admin';

  -- 07 the newcomer now passes the platform-admin check
  select count(*) into v_n from public.organizations;  -- reads all schools without error
  v_log := v_log || E'\n' || case when private.is_platform_admin() then 'PASS' else 'FAIL' end || ' 07 newcomer is a platform admin';

  -- 08 the code is used up, and attempts were cleared
  execute 'reset role';
  select count(*) into v_n from private.platform_invite_codes
    where id = v_invite and redeemed_by = 'test_newcomer' and redeemed_at is not null;
  select v_n + count(*) * 100 into v_n from private.platform_invite_attempts where clerk_user_id = 'test_newcomer';
  v_log := v_log || E'\n' || case when v_n = 1 then 'PASS' else 'FAIL' end || ' 08 code marked used, attempts cleared [' || v_n || ']';

  -- 09 someone else can't reuse it
  perform set_config('request.jwt.claims', '{"sub":"test_other","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_invite(v_code, 'Other Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id is null then 'PASS' else 'FAIL' end || ' 09 used code rejected';

  -- 10 an existing admin redeeming gets their row back and doesn't use up a code
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.invite_id, c.code into v_invite2, v_code2 from public.create_platform_invite(null) c;
  v_admin := public.redeem_platform_invite(v_code2, 'Dummy Admin');
  execute 'reset role';
  select count(*) into v_n from private.platform_invite_codes where id = v_invite2 and redeemed_at is null;
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id = 'user_dummy_platform_admin' and v_n = 1
        then 'PASS' else 'FAIL' end || ' 10 existing admin keeps their row; code stays unused';

  -- 11 a cancelled code doesn't work, and can't be cancelled twice
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.revoke_platform_invite(v_invite2);
  begin
    perform public.revoke_platform_invite(v_invite2);
    v_log := v_log || E'\nFAIL 11a cancelled twice';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like '%already been used or cancelled%' then 'PASS' else 'FAIL' end || ' 11a cannot cancel twice [' || sqlerrm || ']';
  end;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_other","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_invite(v_code2, 'Other Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id is null then 'PASS' else 'FAIL' end || ' 11b cancelled code rejected';

  -- 12 an expired code doesn't work
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.invite_id, c.code into v_invite2, v_code2 from public.create_platform_invite('to expire') c;
  execute 'reset role';
  update private.platform_invite_codes set expires_at = now() - interval '1 minute' where id = v_invite2;
  perform set_config('request.jwt.claims', '{"sub":"test_other","role":"authenticated"}', true);
  execute 'set local role authenticated';
  v_admin := public.redeem_platform_invite(v_code2, 'Other Person');
  v_log := v_log || E'\n' || case when v_admin.clerk_user_id is null then 'PASS' else 'FAIL' end || ' 12 expired code rejected';

  -- 13 the list shows each code's status and who made or used it
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select l.status into v_status from public.list_platform_invites() l where l.invite_id = v_invite;
  select count(*) into v_n from public.list_platform_invites() l
    where (l.invite_id = v_invite and l.status = 'used' and l.redeemed_by_name = 'New Person' and l.created_by_name is not null)
       or (l.invite_id = v_invite2 and l.status = 'expired');
  v_log := v_log || E'\n' || case when v_n = 2 then 'PASS' else 'FAIL' end || ' 13 list shows used and expired [' || coalesce(v_status, 'none') || ']';

  -- 14 after 5 wrong codes in an hour, redeeming is blocked (test_other has 3 so far)
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_other","role":"authenticated"}', true);
  execute 'set local role authenticated';
  perform public.redeem_platform_invite('NOPE-NOPE-NOP1', 'Other Person');
  perform public.redeem_platform_invite('NOPE-NOPE-NOP2', 'Other Person');
  begin
    perform public.redeem_platform_invite('NOPE-NOPE-NOP3', 'Other Person');
    v_log := v_log || E'\nFAIL 14 sixth try allowed';
  exception when others then
    v_log := v_log || E'\n' || case when sqlerrm like 'Too many wrong codes%' then 'PASS' else 'FAIL' end || ' 14 blocked after 5 wrong codes [' || sqlerrm || ']';
  end;

  -- 15 a turned-off admin can't use a code to get back in
  execute 'reset role';
  update public.platform_admins set is_active = false where clerk_user_id = 'test_newcomer';
  perform set_config('request.jwt.claims', '{"sub":"user_dummy_platform_admin","role":"authenticated"}', true);
  execute 'set local role authenticated';
  select c.code into v_code2 from public.create_platform_invite('rejoin') c;
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"sub":"test_newcomer","role":"authenticated"}', true);
  execute 'set local role authenticated';
  begin
    perform public.redeem_platform_invite(v_code2, 'New Person');
    v_log := v_log || E'\nFAIL 15 turned-off admin rejoined with a code';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 15 turned-off admin refused [' || sqlerrm || ']';
  end;

  -- 16 anon can't redeem
  execute 'reset role';
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  execute 'set local role anon';
  begin
    perform public.redeem_platform_invite('ABCD-EFGH-2345', 'Anon');
    v_log := v_log || E'\nFAIL 16 anon called redeem_platform_invite';
  exception when others then
    v_log := v_log || E'\n' || case when sqlstate = '42501' then 'PASS' else 'FAIL' end || ' 16 anon cannot redeem [' || sqlerrm || ']';
  end;

  raise exception 'ROLLBACK';
  exception when others then
    if sqlerrm <> 'ROLLBACK' then
      v_log := v_log || E'\nERROR (test stopped early): ' || sqlerrm;
    end if;
  end;
  insert into test_reports values ('07_platform_invites', v_log);
end;
$test$;

select test,
       (length(report) - length(replace(report, 'PASS ', ''))) / 5 as passed,
       (length(report) - length(replace(report, 'FAIL ', ''))) / 5
         + (length(report) - length(replace(report, 'ERROR ', ''))) / 6 as failed,
       report
from test_reports order by test;
